import React, { useState } from 'react';

// ── Seeded RNG ────────────────────────────────────────────────────
function seededRng(id) {
  let h = 2166136261;
  for (let i = 0; i < id.length; i++) {
    h ^= id.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return () => { h ^= h << 13; h ^= h >> 17; h ^= h << 5; return (h >>> 0) / 0xFFFFFFFF; };
}

// ── Colour helpers ────────────────────────────────────────────────
function darken(hex, amt = 0.35) {
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return `rgb(${Math.round(r*(1-amt))},${Math.round(g*(1-amt))},${Math.round(b*(1-amt))})`;
}
function lighten(hex, amt = 0.55) {
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return `rgb(${Math.min(255,Math.round(r+(255-r)*amt))},${Math.min(255,Math.round(g+(255-g)*amt))},${Math.min(255,Math.round(b+(255-b)*amt))})`;
}
function toVeryDark(hex) {
  // near-black but retains colour hue — for Neuromancer bg
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return `rgb(${Math.round(r*0.12+4)},${Math.round(g*0.14+4)},${Math.round(b*0.10+4)})`;
}

// ── Classify book — Neuromancer vs Loeb ───────────────────────────
const NEURO_GENRES = new Set([
  'classics','philosophy','theory','ancient','political theory','critical theory',
  'ancient history','greek','latin','continental philosophy','metaphysics',
  'epistemology','phenomenology','ethics','logic','aesthetics',
]);
const NEURO_AUTHORS = [
  'plato','aristotle','marx','hegel','kant','foucault','nietzsche','hume',
  'descartes','spinoza','leibniz','locke','rousseau','hobbes','wittgenstein',
  'heidegger','sartre','camus','derrida','althusser','lukács','gramsci',
  'socrates','thucydides','herodotus','homer','virgil','cicero','tacitus',
  'marcus aurelius','seneca','epictetus','augustine','aquinas','machiavelli',
  'confucius','laozi','zhuangzi','sun tzu','ibn khaldun','averroes',
];

function isNeuromancerStyle(book) {
  const genre = (book.genre||'').toLowerCase();
  const author = (book.author||'').toLowerCase();
  if (NEURO_GENRES.has(genre)) return true;
  if (NEURO_AUTHORS.some(a => author.includes(a))) return true;
  // Also check title keywords
  const title = (book.title||'').toLowerCase();
  const classicTitles = ['republic','iliad','odyssey','aeneid','capital','critique','phenomenology','being','ethics','meditations','symposium','apology','nicomachean','leviathan','discourse','genealogy','discipline'];
  if (classicTitles.some(t => title.includes(t))) return true;
  return false;
}


// ── 小花 / Bellflower ─────────────────────────────────────────────
// Grey tabby, white chest, olive eyes. Based on her actual SVG shape.

export function XiaoHuaSVG({ size = 60, style = {} }) {
  return (
    <svg width={size} height={size} viewBox="0 0 128 128" xmlns="http://www.w3.org/2000/svg" style={style}>
      {/* Body — grey tabby */}
      <path d="M114.67,70.19C112.71,44.22,94.44,26.3,64,26.3S15.25,45.33,13.45,71.31c-1.05,15.14,4.58,28.63,15.91,36.32c7.46,5.07,17.88,7.88,34.77,7.88c17.18,0,27.03-3.71,34.49-8.73C111.05,98.43,115.8,85.11,114.67,70.19z" fill="#c8c4bc"/>
      {/* Left ear */}
      <g>
        <path d="M53.72,42.6C46.3,23.4,30.1,10.34,23.87,8.39c-2.35-0.74-5.3-0.81-6.63,1.35c-3.36,5.45-7.66,22.95,1.85,47.78L53.72,42.6z" fill="#b8b4ac"/>
        <path d="M36.12,34.21c1.54-1.29,2.29-2.55,0.6-5.16c-2.62-4.05-7.33-8.78-9.16-10.23c-3-2.38-5.32-3.18-6.21,0.65c-1.65,7.08-1.52,16.69,0.25,21.99c0.62,1.87,2.54,2.86,4.02,1.57L36.12,34.21z" fill="#d49090"/>
      </g>
      {/* Left ear inner mark */}
      <path d="M54.12,45.02c1.13,0.96,3.42,0.82,4.75-0.72c1.61-1.87,3.29-8.17,2.24-17.91c-4.67,0.17-9.09,0.84-13.21,1.97C51.23,33.82,52.03,43.24,54.12,45.02z" fill="#a8a4a0"/>
      {/* Right ear inner mark */}
      <path d="M73.88,45.02c-1.13,0.96-3.42,0.82-4.75-0.72c-1.61-1.87-3.29-8.17-2.24-17.91c4.67,0.17,9.09,0.84,13.21,1.97C76.77,33.82,75.97,43.24,73.88,45.02z" fill="#a8a4a0"/>
      {/* Right ear */}
      <path d="M79.9,29.22c8.08-12.41,19.38-20.75,24.07-22.24c2.32-0.74,5.02-0.62,6.34,1.55c3.32,5.45,6.13,22.24-0.42,45.75L85.96,42.74L79.9,29.22z" fill="#b8b4ac"/>
      <path d="M97.55,38.23c2.43,2.43,4.41,4.06,5.84,5.61c0.95,1.03,2.69,0.56,2.97-0.82c2.45-11.8,1.67-21.86,0-24.5c-0.8-1.26-2.29-1.59-3.65-1.13c-2.44,0.81-8.66,5.45-13.05,12.22c-0.51,0.79-0.32,1.85,0.46,2.38C91.7,33.06,94.46,35.13,97.55,38.23z" fill="#d49090"/>
      {/* Nose */}
      <path d="M55.67,77.75c-0.05-3.08,4.37-4.55,8.54-4.62c4.18-0.07,8.68,1.29,8.73,4.37c0.05,3.08-5.22,7.13-8.54,7.13C61.09,84.63,55.73,80.82,55.67,77.75z" fill="#d87878"/>
      {/* Whiskers */}
      <g>
        <g>
          <path d="M6.7,71.03c0.34,0.41,4.41,0.35,14.36,5.07" fill="none" stroke="#9E9E9E" strokeLinecap="round" strokeMiterlimit="10" strokeWidth="3"/>
          <path d="M2.9,82.86c0,0,6.42-2.24,17.46-0.28" fill="none" stroke="#9E9E9E" strokeLinecap="round" strokeMiterlimit="10" strokeWidth="3"/>
          <path d="M8.81,92.29c0,0,2.74-1.38,12.67-2.25" fill="none" stroke="#9E9E9E" strokeLinecap="round" strokeMiterlimit="10" strokeWidth="3"/>
        </g>
        <g>
          <path d="M120.87,67.51c0,0-3.41,0.33-13.94,6.34" fill="none" stroke="#9E9E9E" strokeLinecap="round" strokeMiterlimit="10" strokeWidth="3"/>
          <path d="M122.42,78.49c0,0-5.09-0.36-16.05,1.97" fill="none" stroke="#9E9E9E" strokeLinecap="round" strokeMiterlimit="10" strokeWidth="3"/>
          <path d="M120.45,89.05c0,0-4.83-1.71-14.78-2.25" fill="none" stroke="#9E9E9E" strokeLinecap="round" strokeMiterlimit="10" strokeWidth="3"/>
        </g>
      </g>
      {/* Right eye — olive green */}
      <path d="M96.09,66.37c-0.34,5.51-3.76,8.54-7.65,8.54s-7.04-3.88-7.04-8.66c0-4.78,3.28-8.71,7.65-8.47C94.12,58.07,96.37,61.87,96.09,66.37z" fill="#5a7028"/>
      {/* Left eye — olive green */}
      <path d="M46,65.81c0.78,5.61-1.58,9.03-5.49,9.82c-3.91,0.79-7.26-1.84-8.23-6.64c-0.98-4.81,0.9-9.32,5.34-9.97C42.77,58.27,45.36,61.22,46,65.81z" fill="#5a7028"/>
      {/* Mouth / chin marking */}
      <path d="M44.99,85.16c-2.57,1.67,0.47,5.54,2.25,6.85c1.78,1.31,4.98,2.92,9.67,2.44c5.54-0.56,7.13-4.69,7.13-4.69s1.97,4.6,8.82,4.79c6.95,0.19,9.1-3.57,10.04-4.69c0.94-1.13,1.88-4.04,0.28-5.16c-1.6-1.13-2.72,0.28-4.41,2.63c-1.69,2.35-5.16,3.66-8.54,2.06s-3.57-7.04-3.57-7.04l-4.79,0.28c0,0-0.75,4.69-2.91,6.19c-2.16,1.5-7.32,1.88-9.48-1.41C48.53,85.95,47.15,83.75,44.99,85.16z" fill="#2e2c2a"/>
      {/* Tabby stripes on forehead */}
      <path d="M48,52 Q52,46 56,50" fill="none" stroke="#8a8480" strokeWidth="2.5" strokeLinecap="round"/>
      <path d="M72,50 Q76,46 80,52" fill="none" stroke="#8a8480" strokeWidth="2.5" strokeLinecap="round"/>
      <path d="M57,44 Q64,40 71,44" fill="none" stroke="#8a8480" strokeWidth="2" strokeLinecap="round"/>
      {/* White chest patch */}
      <ellipse cx="64" cy="88" rx="18" ry="14" fill="#f0ece0" opacity="0.7"/>
    </svg>
  );
}

export function XiaoHuaIcon({ size = 20 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 128 128" xmlns="http://www.w3.org/2000/svg">
      <path d="M114.67,70.19C112.71,44.22,94.44,26.3,64,26.3S15.25,45.33,13.45,71.31c-1.05,15.14,4.58,28.63,15.91,36.32c7.46,5.07,17.88,7.88,34.77,7.88c17.18,0,27.03-3.71,34.49-8.73C111.05,98.43,115.8,85.11,114.67,70.19z" fill="#c8c4bc"/>
      <path d="M53.72,42.6C46.3,23.4,30.1,10.34,23.87,8.39c-2.35-0.74-5.3-0.81-6.63,1.35c-3.36,5.45-7.66,22.95,1.85,47.78L53.72,42.6z" fill="#b8b4ac"/>
      <path d="M36.12,34.21c1.54-1.29,2.29-2.55,0.6-5.16c-2.62-4.05-7.33-8.78-9.16-10.23c-3-2.38-5.32-3.18-6.21,0.65c-1.65,7.08-1.52,16.69,0.25,21.99c0.62,1.87,2.54,2.86,4.02,1.57L36.12,34.21z" fill="#d49090"/>
      <path d="M79.9,29.22c8.08-12.41,19.38-20.75,24.07-22.24c2.32-0.74,5.02-0.62,6.34,1.55c3.32,5.45,6.13,22.24-0.42,45.75L85.96,42.74L79.9,29.22z" fill="#b8b4ac"/>
      <path d="M97.55,38.23c2.43,2.43,4.41,4.06,5.84,5.61c0.95,1.03,2.69,0.56,2.97-0.82c2.45-11.8,1.67-21.86,0-24.5c-0.8-1.26-2.29-1.59-3.65-1.13c-2.44,0.81-8.66,5.45-13.05,12.22c-0.51,0.79-0.32,1.85,0.46,2.38C91.7,33.06,94.46,35.13,97.55,38.23z" fill="#d49090"/>
      <path d="M96.09,66.37c-0.34,5.51-3.76,8.54-7.65,8.54s-7.04-3.88-7.04-8.66c0-4.78,3.28-8.71,7.65-8.47C94.12,58.07,96.37,61.87,96.09,66.37z" fill="#5a7028"/>
      <path d="M46,65.81c0.78,5.61-1.58,9.03-5.49,9.82c-3.91,0.79-7.26-1.84-8.23-6.64c-0.98-4.81,0.9-9.32,5.34-9.97C42.77,58.27,45.36,61.22,46,65.81z" fill="#5a7028"/>
      <path d="M55.67,77.75c-0.05-3.08,4.37-4.55,8.54-4.62c4.18-0.07,8.68,1.29,8.73,4.37c0.05,3.08-5.22,7.13-8.54,7.13C61.09,84.63,55.73,80.82,55.67,77.75z" fill="#d87878"/>
    </svg>
  );
}

function hashColor(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) hash = str.charCodeAt(i) + ((hash << 5) - hash);
  const h = Math.abs(hash) % 360;
  return `hsl(${h}, 35%, 45%)`;
}

export function BookSpine({ book, height = 120, onClick, selected }) {
  const color = book.color || hashColor(book.title);
  const style = book.coverStyle || 'color';

  const spineWidth = Math.max(18, Math.min(32, Math.floor(((book.pages || 300) / 800) * 36) + 12));

  let bg, textColor;
  if (style === 'dark') { bg = '#1a1814'; textColor = 'rgba(255,255,255,0.85)'; }
  else if (style === 'minimal') { bg = '#f8f6f2'; textColor = '#2a2820'; }
  else if (style === 'warm') { bg = '#f5e6cc'; textColor = '#3a2e1a'; }
  else { bg = color; textColor = 'rgba(255,255,255,0.92)'; }

  return (
    <div
      onClick={onClick}
      title={`${book.title} — ${book.author}`}
      style={{
        width: spineWidth,
        height,
        background: bg,
        borderRadius: '2px 3px 3px 2px',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        cursor: 'pointer',
        position: 'relative',
        boxShadow: selected
          ? `0 0 0 2px var(--ink), 2px 2px 6px rgba(0,0,0,0.25)`
          : '1px 1px 4px rgba(0,0,0,0.15), inset -1px 0 0 rgba(0,0,0,0.08)',
        transition: 'transform 0.15s, box-shadow 0.15s',
        flexShrink: 0,
      }}
      onMouseEnter={e => { e.currentTarget.style.transform = 'translateY(-4px)'; }}
      onMouseLeave={e => { e.currentTarget.style.transform = 'translateY(0)'; }}
    >
      {/* Left edge shadow */}
      <div style={{
        position: 'absolute', left: 0, top: 0, bottom: 0, width: 3,
        background: 'rgba(0,0,0,0.18)', borderRadius: '2px 0 0 2px',
      }} />
      {/* Rotated title */}
      <div style={{
        writingMode: 'vertical-rl',
        textOrientation: 'mixed',
        transform: 'rotate(180deg)',
        fontSize: 9,
        fontWeight: 500,
        color: textColor,
        letterSpacing: '0.03em',
        padding: '4px 2px',
        overflow: 'hidden',
        maxHeight: height - 16,
        textOverflow: 'ellipsis',
        whiteSpace: 'nowrap',
        lineHeight: 1.2,
        fontFamily: 'var(--font-serif)',
      }}>
        {book.title}
      </div>
    </div>
  );
}

export function BookCard({ book, status, onClick, selected }) {
  const color = book.color || hashColor(book.title);
  const style = book.coverStyle || 'color';

  let bg, textColor, accentBg;
  if (style === 'dark') { bg = '#1a1814'; textColor = 'rgba(255,255,255,0.85)'; accentBg = 'rgba(255,255,255,0.08)'; }
  else if (style === 'minimal') { bg = '#f8f6f2'; textColor = '#2a2820'; accentBg = 'rgba(0,0,0,0.05)'; }
  else if (style === 'warm') { bg = '#f5e6cc'; textColor = '#3a2e1a'; accentBg = 'rgba(0,0,0,0.06)'; }
  else { bg = color; textColor = 'rgba(255,255,255,0.92)'; accentBg = 'rgba(255,255,255,0.12)'; }

  const pct = book.pages ? Math.min(100, Math.round((book.progress / book.pages) * 100)) : 0;

  return (
    <div
      onClick={onClick}
      style={{
        width: 120,
        background: bg,
        borderRadius: 6,
        overflow: 'hidden',
        cursor: 'pointer',
        boxShadow: selected
          ? `0 0 0 2px var(--ink), 3px 4px 12px rgba(0,0,0,0.22)`
          : '2px 3px 10px rgba(0,0,0,0.14)',
        transition: 'transform 0.15s, box-shadow 0.15s',
        position: 'relative',
        flexShrink: 0,
      }}
      onMouseEnter={e => { e.currentTarget.style.transform = 'translateY(-4px)'; e.currentTarget.style.boxShadow = '3px 6px 16px rgba(0,0,0,0.22)'; }}
      onMouseLeave={e => { e.currentTarget.style.transform = 'none'; e.currentTarget.style.boxShadow = selected ? `0 0 0 2px var(--ink), 3px 4px 12px rgba(0,0,0,0.22)` : '2px 3px 10px rgba(0,0,0,0.14)'; }}
    >
      {/* Cover face */}
      <div style={{ height: 160, padding: '16px 12px 12px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
        <div>
          <div style={{ fontSize: 11, fontWeight: 600, color: textColor, lineHeight: 1.35, marginBottom: 4, fontFamily: 'var(--font-serif)' }}>
            {book.title}
          </div>
          <div style={{ fontSize: 9, color: textColor, opacity: 0.7, fontStyle: 'italic' }}>{book.author}</div>
        </div>
        {/* Decorative line */}
        <div style={{ height: 1, background: textColor, opacity: 0.2, margin: '8px 0' }} />
        <div style={{ fontSize: 9, color: textColor, opacity: 0.6, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
          {book.year < 0 ? `${Math.abs(book.year)} BCE` : book.year}
        </div>
      </div>

      {/* Progress bar for reading */}
      {book.status === 'reading' && book.pages && (
        <div style={{ height: 3, background: accentBg }}>
          <div style={{ height: '100%', width: `${pct}%`, background: textColor, opacity: 0.6, transition: 'width 0.3s' }} />
        </div>
      )}

      {/* Status ribbon */}
      {status && (
        <div style={{ background: accentBg, padding: '4px 8px', fontSize: 8, color: textColor, opacity: 0.85, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.04em' }}>
          {status.label.toUpperCase()}
        </div>
      )}
    </div>
  );
}
